function AuthProvider({children}) { const [session,setSession] = useState(()=>{ try{return JSON.parse(localStorage.getItem('chromora-session')) || {token:null,user:null}}catch{return {token:null,user:null}}}); const login=data=>{const next={token:data.token,user:data.user};localStorage.setItem('chromora-session',JSON.stringify(next));setSession(next)}; const logout=()=>{localStorage.removeItem('chromora-session');setSession({token:null,user:null})}; return <Auth.Provider value={{...session,login,logout}}>{children}</Auth.Provider> }
function useAuth(){return useContext(Auth)}
function PublicBackground(){return <><div className="landing-background" aria-hidden="true"/><div className="landing-background-overlay" aria-hidden="true"/></>}
function PublicSectionLink({section,children,className=''}){const navigate=useNavigate();const location=useLocation();const go=e=>{e.preventDefault();if(location.pathname==='/'||location.pathname==='/welcome')document.getElementById(section)?.scrollIntoView({behavior:'smooth',block:'start'});else navigate(`/#${section}`)};return <a className={className} href={`/#${section}`} onClick={go}>{children}</a>}
function PublicNav({active}){const navigate=useNavigate();const location=useLocation();const home=e=>{e.preventDefault();if(location.pathname==='/'||location.pathname==='/welcome')window.scrollTo({top:0,behavior:'smooth'});else navigate('/')};return <nav className="landing-nav public-nav" aria-label="Public navigation"><a className="landing-brand" href="/" onClick={home} aria-label="Chromora home"><Logo/></a><div className="landing-nav-links"><PublicSectionLink section="workflow" className={active==='workflow'?'active':''}>Workflow</PublicSectionLink><PublicSectionLink section="integrity" className={active==='integrity'?'active':''}>Integrity</PublicSectionLink><PublicSectionLink section="about" className={active==='about'?'active':''}>About</PublicSectionLink><NavLink className="landing-command-link" to="/login">Login</NavLink></div></nav>}
function PublicFooter(){return <footer className="landing-footer public-footer"><div className="landing-shell footer-grid"><div className="footer-brand"><Logo/><span>Digital Companion for Field Drug Testing</span></div><div><b>PRODUCT</b><PublicSectionLink section="workflow">Workflow</PublicSectionLink><PublicSectionLink section="integrity">Integrity</PublicSectionLink><PublicSectionLink section="about">About</PublicSectionLink></div><div><b>PROJECT</b><a href="https://github.com/Undead5z/Chromora" target="_blank" rel="noreferrer">GitHub</a><a href="https://github.com/Undead5z/Chromora/blob/main/DEMO.md" target="_blank" rel="noreferrer">Prototype Demo</a><NavLink to="/login">Command Centre</NavLink></div></div><p className="footer-disclaimer">Presumptive field-test support only &middot; Laboratory confirmation remains the confirmatory process.</p><div className="landing-shell footer-bottom"><span>&copy; 2026 Chromora &middot; Team Auditore Vanguard</span><span>SIH26231 &middot; Smart India Hackathon 2026</span></div></footer>}
function Landing(){const location=useLocation();const [active,setActive]=useState('hero');const sections=[['hero','Go to Hero'],['workflow','Go to Workflow'],['integrity','Go to Evidence Integrity'],['about','Go to About']];useEffect(()=>{if(location.hash){const id=location.hash.slice(1);requestAnimationFrame(()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'}))}},[location.hash]);useEffect(()=>{const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){if(entry.target.dataset.landingSection)setActive(entry.target.id);if(entry.target.dataset.reveal)entry.target.classList.add('is-visible')}}),{threshold:.22,rootMargin:'-12% 0px -35%'});document.querySelectorAll('[data-landing-section],[data-reveal]').forEach(element=>observer.observe(element));return()=>observer.disconnect()},[]);const scrollTo=id=>document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'});const workflow=[['01','CAPTURE','Capture the test result together with its reference colour card.','capture-diagram','EVIDENCE FRAME'],['02','CALIBRATE','Use the reference card to prepare the image for controlled colour comparison when a validated profile is available.','calibrate-diagram','REFERENCE CARD'],['03','CLASSIFY','Generate only a presumptive result when a validated classifier is available.','classify-diagram','ANALYSIS PENDING'],['04','SECURE','Preserve original evidence with operator, time, location, SHA-256 fingerprint and signed record.','secure-diagram','SIGNED RECORD']];return <main className="landing landing-experience public-page"><PublicBackground/><PublicNav active={active}/><div className="landing-dots" aria-label="Landing sections">{sections.map(([id,label])=><button key={id} className={active===id?'active':''} onClick={()=>scrollTo(id)} aria-label={label} title={label}><span/></button>)}</div><section id="hero" className="landing-hero" data-landing-section><div className="landing-shell landing-hero-grid"><div className="landing-hero-copy" data-reveal><p className="landing-eyebrow">DIGITAL COMPANION FOR FIELD DRUG TESTING</p><h1>Digital Companion<br/>for <em>Field Drug Testing</em></h1><p className="landing-lede">Capture. Calibrate. Classify. Secure.</p><p className="landing-body">Chromora supports the field-testing workflow by combining guided image capture, reference-card context, traceable metadata and tamper-evident digital records.</p><NavLink className="landing-primary-button" to="/login">Enter Command Centre <span>&rarr;</span></NavLink><small>Presumptive field-test support only. Laboratory confirmation remains the confirmatory process.</small></div><div className="landing-product-visual" data-reveal style={{'--reveal-delay':'110ms'}}><div className="visual-orbit orbit-one"/><div className="visual-orbit orbit-two"/><div className="capture-console"><div className="console-top"><span>CHROMORA CAPTURE</span><b>SECURE RECORD</b></div><div className="capture-screen"><div className="capture-corners"/><div className="capture-target"><i/><span>REFERENCE CARD</span></div><div className="reference-card"><small>COLOUR REFERENCE</small><i/><i/><i/></div><div className="scan-line"/></div><div className="console-footer"><div><small>ORIGINAL EVIDENCE</small><b>SHA-256 READY</b></div><div className="secure-pill"><span>&#10003;</span> PROTECTED</div></div></div><div className="visual-callout"><span>&#9679;</span> EVIDENCE CAPTURE</div></div></div></section><section id="workflow" className="landing-workflow landing-section" data-landing-section><div className="landing-shell"><header className="section-heading" data-reveal><p className="landing-eyebrow">THE WORKFLOW</p><h2>Clear stages.<br/><em>Truthful states.</em></h2><p>Chromora separates field capture, contextual metadata, analysis status and evidence protection instead of hiding them behind a single AI result.</p></header><div className="workflow-grid">{workflow.map(([number,title,copy,visual,status],index)=><article className="workflow-card" key={title} data-reveal style={{'--reveal-delay':`${index*70}ms`}}><div className="workflow-card-head"><b>{number}</b><span>{status}</span></div><div><h3>{title}</h3><p>{copy}</p></div><div className={`workflow-diagram ${visual}`} aria-hidden="true">{title==='CAPTURE'&&<><i/><i/><i/></>}{title==='CALIBRATE'&&<><i/><i/><i/><i/></>}{title==='CLASSIFY'&&<><i/><i/><i/></>}{title==='SECURE'&&<><i>&#10003;</i><span>SHA-256 &rarr; ECDSA P-256</span></>}</div></article>)}</div></div></section><section id="integrity" className="landing-integrity landing-section" data-landing-section><div className="landing-shell integrity-layout"><header className="section-heading" data-reveal><p className="landing-eyebrow">EVIDENCE INTEGRITY</p><h2>A record with<br/>a <em>visible chain.</em></h2><p>Every captured evidence image can be verified against its original cryptographic fingerprint and signed operational record.</p></header><div className="integrity-panel" data-reveal style={{'--reveal-delay':'90ms'}}><div className="integrity-chain"><div><span>01</span><b>ORIGINAL IMAGE</b><small>Protected source evidence</small></div><i>&darr;</i><div><span>02</span><b>SHA-256 FINGERPRINT</b><small>Unique image hash</small></div><i>&darr;</i><div><span>03</span><b>SIGNED RECORD</b><small>ECDSA P-256 signature</small></div><i>&darr;</i><div><span>04</span><b>FRESH VERIFICATION</b><small>Current evidence comparison</small></div><i>&darr;</i><strong><span>&#10003;</span> VERIFIED / MISMATCH</strong></div><p>If the image or a protected signed field is changed later, verification can expose the mismatch rather than silently accepting the modified record.</p><div className="tech-strip"><span>SHA-256</span><span>ECDSA P-256</span><span>GPS</span><span>TIMESTAMP</span><span>OPERATOR ID</span></div></div></div></section><section id="about" className="landing-about landing-section" data-landing-section><div className="landing-shell about-layout"><div className="about-copy" data-reveal><p className="landing-eyebrow">ABOUT CHROMORA</p><h2>Built for the field.<br/><em>Designed for traceability.</em></h2><p>Chromora combines guided field capture, contextual metadata, evidence protection and searchable records into one focused workflow for presumptive field drug testing. It is designed to support existing colorimetric test kits without introducing new testing hardware.</p><div className="about-cta"><p><b>Prototype in Progress</b><span>Explore the current Chromora build, source code and prototype demonstration as development continues.</span></p><div><a className="landing-primary-button" href="https://github.com/Undead5z/Chromora/blob/main/DEMO.md" target="_blank" rel="noreferrer">Watch Demo <span>&rarr;</span></a><a className="landing-secondary-button" href="https://github.com/Undead5z/Chromora" target="_blank" rel="noreferrer">View GitHub <span>&rarr;</span></a></div></div></div><div className="about-bento">{[['MOBILE FIELD COMPANION','Guided image capture, officer-linked records, GPS support and field-friendly workflows from a mobile device.'],['WEB COMMAND CENTRE','Search, review and manage field-test records from one centralized Web interface.'],['EVIDENCE INTEGRITY','Original images are fingerprinted using SHA-256 and protected with digitally signed records so later changes can be detected.'],['HUMAN / LAB BOUNDARY','Chromora records presumptive field-test information only. Laboratory confirmation remains the confirmatory process.'],['NO NEW HARDWARE','Designed to work alongside existing colorimetric field-test kits using a standard smartphone camera.']].map(([title,copy],index)=><article key={title} data-reveal style={{'--reveal-delay':`${index*70}ms`}}><span>{String(index+1).padStart(2,'0')}</span><h3>{title}</h3><p>{copy}</p></article>)}</div></div><div className="about-tech" data-reveal><span>REACT NATIVE</span><span>REACT</span><span>NODE.JS</span><span>EXPRESS</span><span>SQLITE</span><span>SHA-256</span><span>ECDSA P-256</span></div><p className="about-note">Presumptive field-test support only. Chromora does not replace laboratory confirmatory testing.</p></section><PublicFooter/></main>}
function Login(){const {login,token}=useAuth();const nav=useNavigate();const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[showPassword,setShowPassword]=useState(false),[error,setError]=useState(''),[busy,setBusy]=useState(false),[authView,setAuthView]=useState('login'),[registration,setRegistration]=useState({fullName:'',officialEmail:'',phone:'',department:'',designation:'',requestedRole:'FIELD_OFFICER',jurisdictionRegion:'',password:'',confirmPassword:''}),[registrationError,setRegistrationError]=useState(''),[registrationBusy,setRegistrationBusy]=useState(false),[registrationSuccess,setRegistrationSuccess]=useState(false);useEffect(()=>{if(token&&authView==='login')nav('/dashboard')},[token,nav,authView]);useEffect(()=>{const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting)entry.target.classList.add('is-visible')}),{threshold:.15});document.querySelectorAll('.login-experience [data-reveal]').forEach(element=>observer.observe(element));return()=>observer.disconnect()},[]);const cleanError=message=>{const text=String(message||'');if(text.includes('pending approval'))return'Your registration is awaiting administrator approval.';if(text.includes('was rejected'))return'Your registration request was rejected.';if(text.includes('has been suspended'))return'Your account has been suspended. Contact an administrator.';if(text.startsWith('[')||text.includes('ZodError'))return'Please check the required registration fields.';return text||'Unable to complete this request.'};const handleLogin=async event=>{event.preventDefault();setBusy(true);setError('');try{login(await request('/auth/login',{method:'POST',body:{email,password,application:'WEB'}}));nav('/dashboard')}catch(e){setError(cleanError(e.message))}finally{setBusy(false)}};const updateRegistration=(key,value)=>setRegistration(current=>({...current,[key]:value}));const openRegistration=event=>{event.preventDefault();event.stopPropagation();setAuthView('register');setRegistrationError('');setRegistrationSuccess(false)};const backToLogin=event=>{event?.preventDefault();event?.stopPropagation();setAuthView('login');setRegistrationError('');setRegistrationSuccess(false)};const handleRegister=async event=>{event.preventDefault();setRegistrationError('');if(registration.password!==registration.confirmPassword){setRegistrationError('Passwords do not match.');return}if(registration.requestedRole==='FIELD_OFFICER'&&!registration.jurisdictionRegion.trim()){setRegistrationError('Jurisdiction / Region is required for Field Officers.');return}setRegistrationBusy(true);try{await request('/auth/register',{method:'POST',body:registration});setRegistrationSuccess(true)}catch(e){setRegistrationError(cleanError(e.message))}finally{setRegistrationBusy(false)}};const passwordToggle=<button type="button" onClick={()=>setShowPassword(value=>!value)} aria-label={showPassword?'Hide password':'Show password'} aria-pressed={showPassword}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.7"/>{showPassword&&<path d="M4 4l16 16"/>}</svg></button>;return <main className="landing landing-experience login-experience public-page"><PublicBackground/><PublicNav active="login"/><section className="login-experience-main"><div className="landing-shell login-experience-grid"><section className="login-brand-panel" data-reveal><Logo/><p className="landing-eyebrow">CHROMORA WEB COMMAND CENTRE</p><h1>Secure field-test records.<br/><em>Built for traceability.</em></h1><p>Review protected operational records with a workflow designed for accountable field documentation.</p><div className="login-brand-status"><span>GUIDED CAPTURE</span><i/><span>TRACEABLE METADATA</span><i/><span>SECURE RECORD</span></div></section><section className={`login-glass-card ${authView==='register'?'registration-card':''}`} data-reveal style={{'--reveal-delay':'100ms'}}>{authView==='login'?<form onSubmit={handleLogin}><p className="landing-eyebrow">WELCOME BACK</p><h2>Sign in securely.</h2><p>Sign in to your approved Chromora account.</p><label>Official Email<input value={email} onChange={e=>setEmail(e.target.value)} type="email" autoComplete="username" placeholder="name@example.com" required/></label><label>Password<span className="password-field"><input value={password} onChange={e=>setPassword(e.target.value)} type={showPassword?'text':'password'} autoComplete="current-password" placeholder="Enter password" required/>{passwordToggle}</span></label>{error&&<div className="form-error" role="alert">{error}</div>}<button className="login-submit" type="submit" disabled={busy}>{busy?'Signing in...':'Sign In'} <span>&rarr;</span></button><button className="login-register-action" type="button" onClick={openRegistration}>REGISTER FOR ACCESS</button><small className="login-security">SECURE &middot; ENCRYPTED &middot; AUDIT READY</small></form>:registrationSuccess?<div className="registration-success"><p className="landing-eyebrow">REGISTRATION SUBMITTED</p><h2>Registration submitted</h2><p>Your account is awaiting administrator approval. You will be able to sign in once your account is approved.</p><button className="login-submit" type="button" onClick={backToLogin}>BACK TO SIGN IN</button></div>:<form onSubmit={handleRegister}><button className="registration-back" type="button" onClick={backToLogin}>&larr; Back to Sign In</button><p className="landing-eyebrow">REGISTER FOR ACCESS</p><h2>Create your access request.</h2><p>Submit your official details for administrator approval.</p><div className="registration-form-grid"><label>Full Name<input value={registration.fullName} onChange={e=>updateRegistration('fullName',e.target.value)} required/></label><label>Official Email<input value={registration.officialEmail} onChange={e=>updateRegistration('officialEmail',e.target.value)} type="email" required/></label><label>Phone<input value={registration.phone} onChange={e=>updateRegistration('phone',e.target.value)} type="tel" required/></label><label>Department / Office<input value={registration.department} onChange={e=>updateRegistration('department',e.target.value)} required/></label><label>Designation<input value={registration.designation} onChange={e=>updateRegistration('designation',e.target.value)} required/></label><label>Requested Role<select value={registration.requestedRole} onChange={e=>updateRegistration('requestedRole',e.target.value)}><option value="ADMIN">Admin</option><option value="FIELD_OFFICER">Field Officer</option></select></label>{registration.requestedRole==='FIELD_OFFICER'&&<label className="registration-full-width">Jurisdiction / Region<input value={registration.jurisdictionRegion} onChange={e=>updateRegistration('jurisdictionRegion',e.target.value)} required/></label>}<label>Password<span className="password-field"><input value={registration.password} onChange={e=>updateRegistration('password',e.target.value)} type={showPassword?'text':'password'} autoComplete="new-password" minLength="8" required/>{passwordToggle}</span></label><label>Confirm Password<input value={registration.confirmPassword} onChange={e=>updateRegistration('confirmPassword',e.target.value)} type={showPassword?'text':'password'} autoComplete="new-password" minLength="8" required/></label></div>{registrationError&&<div className="form-error" role="alert">{registrationError}</div>}<button className="login-submit" type="submit" disabled={registrationBusy}>{registrationBusy?'SUBMITTING...':'SUBMIT REGISTRATION'} <span>&rarr;</span></button></form>}</section></div></section><PublicFooter/></main>}
